(91, 1, 3, 'Implement Idempotent Event Deduplication in ProcessedEvents Table', 'Atomic insert check preventing duplicate notification generation.', 'DONE', 'HIGH', 4, 1, '2026-11-03', 131072.0, 0, NOW() - INTERVAL 7 DAY, NOW()),
(92, 1, 3, 'Implement Transactional Outbox Table Schema and Indexes', 'Composite index on status and created_at for fast polling queries.', 'DONE', 'HIGH', 1, 1, '2026-11-02', 196608.0, 0, NOW() - INTERVAL 8 DAY, NOW()),
(93, 1, 3, 'Setup Prometheus Metrics Scraper for Spring Boot Actuator', 'Automate 15s scrape interval targeting backend-1 and backend-2.', 'DONE', 'MEDIUM', 6, 1, '2026-11-01', 262144.0, 0, NOW() - INTERVAL 9 DAY, NOW()),
(94, 1, 3, 'Implement Automated Database Vacuum & Index Optimization', 'Scheduled maintenance script verifying B-Tree depth and fragment ratio.', 'TODO', 'LOW', 7, 1, '2026-11-22', 196608.0, 0, NOW() - INTERVAL 16 DAY, NOW()),
(95, 1, 3, 'Create Event Replay Utility for Rebuilding Notifications', 'CLI command to rewind Kafka offsets and reconstruct lost activity logs.', 'TODO', 'MEDIUM', 4, 1, '2026-11-26', 262144.0, 0, NOW() - INTERVAL 20 DAY, NOW()),
(96, 1, 4, 'Conduct Automated Dependency Vulnerability Scan (OWASP / Snyk)', 'Integrate dependency-check plugin into Maven verify phase.', 'IN_PROGRESS', 'HIGH', 2, 1, '2026-11-11', 65536.0, 0, NOW() - INTERVAL 5 DAY, NOW()),
(97, 1, 4, 'Implement Token Revocation Blacklist in Redis upon Logout', 'Store revoked JTI / token hash with TTL equal to remaining token life.', 'DONE', 'HIGH', 1, 1, '2026-10-31', 65536.0, 0, NOW() - INTERVAL 10 DAY, NOW()),
(98, 1, 4, 'Enforce Strict CORS Allowed Origins Matching .env Configuration', 'Reject untrusted origin headers and deny wildcard access credentials.', 'DONE', 'HIGH', 2, 1, '2026-11-01', 131072.0, 0, NOW() - INTERVAL 9 DAY, NOW()),
(99, 1, 4, 'Verify SQL Injection & Parameter Tampering Hardening', 'Ensure 100% of database queries use JPA parameterized query bindings.', 'DONE', 'URGENT', 1, 1, '2026-11-02', 196608.0, 0, NOW() - INTERVAL 8 DAY, NOW()),
(100, 1, 4, 'Sanitize User Input in Task Descriptions and Comment Markdown', 'Prevent stored XSS by escaping HTML entities before database save.', 'DONE', 'HIGH', 3, 1, '2026-11-03', 262144.0, 0, NOW() - INTERVAL 7 DAY, NOW()),
(101, 1, 4, 'Implement Security Audit Log for Password Changes and Role Updates', 'Immutable log records whenever an OWNER or ADMIN elevates user privileges.', 'DONE', 'MEDIUM', 4, 1, '2026-11-04', 327680.0, 0, NOW() - INTERVAL 6 DAY, NOW()),
(102, 1, 4, 'Add CSP Nonce Injection in Next.js Server Components', 'Strict Content-Security-Policy disallowing unsafe-inline script execution.', 'TODO', 'HIGH', 3, 1, '2026-11-17', 65536.0, 0, NOW() - INTERVAL 11 DAY, NOW()),
(103, 2, 5, 'Verify Tenant Data Isolation across Cross-Tenant API Requests', 'Automated test suite proving user B receives 403 when requesting org A.', 'DONE', 'URGENT', 1, 1, '2026-11-05', 65536.0, 0, NOW() - INTERVAL 5 DAY, NOW());
